Let $s,k\in{\mathbb N}$ with $s\leq k$. For every $C_1>0$ there exist constants $C_2=C_2(C_1, P, k),\; C_3=C_3(C_1, P, k)>1$ such that the following holds. Let $G/\Gamma$ be a nilmanifold of degree $k$, step $s$, complexity at most $M \geq 2$, and dimension $m\in{\mathbb N}$, with associated filtration $G_\bullet$, and let $g\in\mathrm{poly}({\mathbb Z}, G)$.  Let $\delta\in(0, 1/10)$, and let $F:G/\Gamma \to \mathbb{C}$ be a $1$-bounded $M$-Lipschitz function with a vertical character $\xi$ satisfying $0<|\xi| \leq M/\delta$.  
Let $\tilde{V} \leq  W^{C_1}$ be a nonnegative integer power of $W$, let $\tilde{r}\in[\tilde{V}]$, and let 

$N\geq \tilde{V}_d \tilde{V}^{C_2} (M/\delta)^{2C_2 dm^{C_2}}$ be an integer.  Lastly, let $A \subseteq [N/\tilde{V}]$ and $B \subseteq {\mathbb Z}$ be nonempty arithmetic progressions of common difference at most $M/\delta$ satisfying 
\begin{align} 
   |B| \geq C_2\cdot(N/(\tilde{V}\tilde{V}_d))^{1/d}(M/\delta)^{-C_2 m^{C_2}}.
\end{align}

If
\begin{equation}
    \sum_{y\in A}\left|\mathbb{E}_{z \in B} e(\tilde{a}(y)\cdot\widetilde{P}_{[\tilde{r},\tilde{V}]}(z))F(g(y + \widetilde{P}_{[\tilde{r},\tilde{V}]}(z))\Gamma) \vphantom{\mathbb{E}_{z \in [(N/W_d)^{1/d}\tilde{V}^{-1}]}} \right| \geq  \delta |A|,
\end{equation}
then 
the following holds with $T:=|B|^d \tilde{V}_d$.
\begin{itemize}
    \item
 When $s>1$: There exists a factorization $g(n) = \varepsilon(n)g'(n)\gamma(n)$, where $\varepsilon$ is $((M/\delta)^{C_3m^{C_3}}, T)$-smooth, $g'$ takes values in an $(M/\delta)^{C_3m^{C_3}}$-rational normal subgroup $G'$ of $G$ such that $G'/\mathrm{ker}(\xi)$ has step at most $s - 1$, and $\gamma$ is $(M/\delta)^{C_3m^{C_3}}$-rational.
    \item When $s=1$ and $k>1$: There is a polynomial $p(n)=\sum_{j=0}^k \alpha_j n^j$ such that $F(g(n)\Gamma)=e(p(n))$, and there is a positive integer $q\leq C_3\delta^{-C_3}$ such that $\left\Vert q\alpha_j\right\Vert_{\mathbb{R}/\mathbb{Z}} \leq C_3\delta^{-C_3}/T^j$ for all $j \geq 2$.
    \item When $s=1$ and $k=1$: There are a phase $\alpha \in \mathbb{R}/\mathbb{Z}$ and a positive integer $q \leq C_3\delta^{-C_3}$ such that $\left\Vert q\tilde{a}(y)-\alpha\right\Vert_{\mathbb{R}/\mathbb{Z}} \leq C_3\delta^{-C_3}/T$ for at least {$C_3\delta^{C_3}|A|$} values of $y \in A$.
\end{itemize}

Let $\delta\in(0, 1/10)$, let $N\in{\mathbb N}$, and let $f_0, f_1, f_2:{\mathbb Z}^2\to{\mathbb C}$ be $1$-bounded functions supported on $[N]^2$. If 
    \begin{align}
        \Lambda^{{\mathrm{Model}}}(f_0, f_1, f_2)\geq \delta N^3,
    \end{align}
    then $\left\Vert f_0\right\Vert^4_{{\mathbf{e}}_1\cdot[\pm N],\; {\mathbf{e}}_2\cdot[\pm N]}, \left\Vert f_1\right\Vert^4_{{\mathbf{e}}_1\cdot[\pm N],\; ({\mathbf{e}}_2-{\mathbf{e}}_1)\cdot[\pm N]}, \left\Vert f_2\right\Vert^4_{{\mathbf{e}}_2\cdot[\pm N],\; ({\mathbf{e}}_2-{\mathbf{e}}_1)\cdot[\pm N]}\gg_d \delta^{O_d(1)} N^2$.

There exists $C = C(P)>0$ such that the following holds. Let $f_0, f_1, f_2:{\mathbb Z}^2\to{\mathbb C}$ be $1$-bounded functions supported on $[N]^2$. If $N, W$ satisfy $N\geq C W^{C}$ and $W\geq \exp\exp(\log(1/\delta)^{C})$, then
    \begin{align*}
        |\Lambda^W(f_0,f_1,f_2)-\Lambda^{\mathrm{Model}}(f_0,f_1,f_2)| <\delta N^2.
    \end{align*}
